// Artikel-Text extrahieren und finalen Payload zusammenbauen
const response = $json;
const choices  = response.choices || [];
if (!choices.length) throw new Error('OpenAI Artikel-Response leer');

const content_markdown = choices[0].message.content.trim();
const meta = $('Keyword-Plan parsen').item.json;

const date = new Date().toISOString().split('T')[0]; // YYYY-MM-DD

// Payload für blog_generator.py zusammenbauen
const payload = {
  title:            meta.title,
  niche:            meta.niche,
  niche_slug:       meta.slug,
  date:             date,
  keyword:          meta.keyword,
  dp_keyword:       meta.dp_keyword,
  section_keywords: meta.section_keywords,
  excerpt:          meta.excerpt,
  meta_description: meta.meta_description,
  content_markdown: content_markdown,
  tags:             meta.tags
};

// Als Base64 kodieren (vermeidet Shell-Quoting-Probleme)
const payloadB64 = Buffer.from(JSON.stringify(payload)).toString('base64');

return [{ json: { ...payload, payload_b64: payloadB64 } }];

// Ergebnis des Python-Skripts parsen
const stdout = $json.stdout || '{}';
const stderr = $json.stderr || '';

let result = {};
try {
  // Letzte JSON-Zeile aus stdout extrahieren
  const lines = stdout.trim().split('\n').filter(l => l.trim().startsWith('{'));
  result = JSON.parse(lines[lines.length - 1] || '{}');
} catch (e) {
  result = { success: false, error: 'JSON parse error: ' + e.message };
}

// Metadata aus Payload ergänzen
const meta = $('Payload vorbereiten').item.json;

return [{
  json: {
    success:   result.success || false,
    slug:      result.slug   || meta.title,
    url:       result.url    || '',
    title:     result.title  || meta.title,
    niche:     result.niche  || meta.niche,
    date:      result.date   || '',
    images:    result.images || [],
    error:     result.error  || '',
    stderr_preview: stderr.slice(-300)
  }
}];
